    const timer = setTimeout(() => {
      setIsExiting(true);
      setTimeout(onComplete, 700); // Wait for fade out transition
    }, 2800);

    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <div 
      className={`fixed inset-0 z-[100] bg-white flex flex-col items-center justify-center transition-opacity duration-700 ease-in-out ${isExiting ? 'opacity-0' : 'opacity-100'}`}
    >
      <div className="relative w-32 h-32 mb-10">
        {/* Yellow Triangle: Left (Bottom-Left) - Animated */}
        <div 
           className="absolute inset-0 bg-brand-yellow" 
           style={{ 
             clipPath: 'polygon(0 0, 0 100%, 100% 100%)',
             animation: 'tumbleInLeft 1.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards'
           }}
        ></div>

        {/* Black Triangle: Right (Top-Right) - Animated */}
        <div 
           className="absolute inset-0 bg-black" 
           style={{ 
             clipPath: 'polygon(0 0, 100% 0, 100% 100%)',
             animation: 'tumbleInRight 1.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards'
           }}
        ></div>
      </div>

      <h1 
        className="text-lg md:text-xl font-light tracking-[0.3em] uppercase text-black opacity-0" 
        style={{ animation: 'fadeInUp 0.8s ease-out 1.2s forwards' }}
      >
        Welcome to my creative space
      </h1>

      <style>{`
        @keyframes tumbleInLeft {
          0% { transform: translate(-100%, 100%) rotate(-45deg) scale(0.5); opacity: 0; }
          60% { transform: translate(5%, -5%) rotate(5deg) scale(1.05); opacity: 1; }
