import React, { useState } from 'react';
import SectionTitle from './SectionTitle';
import { PROJECTS, EXPERIENCES, LOVED_DESIGNS } from '../constants';
import { Project, Experience } from '../types';
import Modal from './Modal';
import { Play, ExternalLink, ArrowUpRight } from 'lucide-react';

interface DesignItem {
  id: string;
  imageUrl: string;
  title: string;
}

const Projects: React.FC = () => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [selectedExperience, setSelectedExperience] = useState<Experience | null>(null);
  const [selectedDesign, setSelectedDesign] = useState<DesignItem | null>(null);

  return (
    <section className="bg-gray-50 py-24 scroll-mt-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Experience Highlight */}
        <div id="experience" className="mb-24 scroll-mt-24">
             <SectionTitle title="Experience" subtitle="Professional timeline." />
             <div className="space-y-8">
                {EXPERIENCES.map((exp) => (
                    <div 
                        key={exp.id} 
                        className="group flex flex-col md:flex-row gap-6 md:gap-12 border-b border-gray-200 pb-8 last:border-0 hover:bg-white hover:p-6 transition-all duration-300 rounded-sm cursor-pointer relative"
                        onClick={() => setSelectedExperience(exp)}
                    >
                         {/* Hover indicator */}
                        <div className="absolute top-6 right-6 opacity-0 group-hover:opacity-100 transition-opacity">
                            <ArrowUpRight size={20} className="text-brand-yellow" />
                        </div>

                        <div className="md:w-1/3">
                            <span className="text-sm text-gray-400 font-mono mb-2 block">{exp.date}</span>
                            <h3 className="text-xl font-bold text-black">{exp.company}</h3>
                            <p className="text-brand-yellow font-medium">{exp.role}</p>
                        </div>
                        <div className="md:w-2/3">
                            <ul className="space-y-2 text-gray-600 font-light">
                                {exp.description.map((item, i) => (
                                    <li key={i} className="leading-relaxed">
                                        • {item}
                                    </li>
                                ))}
                            </ul>
                            {exp.images && exp.images.length > 0 && (
                                <p className="mt-4 text-xs font-bold uppercase tracking-wider text-gray-400 group-hover:text-brand-yellow transition-colors">
                                    View Visuals & Projects
                                </p>
                            )}
                        </div>
                    </div>
                ))}
             </div>
        </div>

        <div id="projects" className="pt-10 scroll-mt-24">
            <SectionTitle title="Work" subtitle="Selected projects." />

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
            {PROJECTS.map((project) => (
                <div 
                  key={project.id} 
                  className="group cursor-pointer"
                  onClick={() => setSelectedProject(project)}
                >
                <div className="aspect-[4/3] overflow-hidden bg-gray-200 mb-6 relative rounded-sm">
                    <img 
                        src={project.imageUrl} 
                        alt={project.title} 
                        className="w-full h-full object-cover transition-transform duration-1000 ease-out group-hover:scale-110"
                    />
                    <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                </div>

                <div>
                    <div className="flex justify-between items-baseline mb-2">
                         <span className="text-xs font-bold uppercase tracking-wider text-brand-yellow">{project.role}</span>
                         <span className="text-xs text-gray-400">{project.date.split('-')[1]?.trim() || project.date}</span>
                    </div>

                    <h3 className="text-xl font-bold mb-2 group-hover:text-brand-yellow transition-colors flex items-center gap-2">
                        {project.title}
                        <ArrowUpRight size={16} className="opacity-0 -translate-y-1 -translate-x-1 group-hover:opacity-100 group-hover:translate-y-0 group-hover:translate-x-0 transition-all" />
                    </h3>

                    <p className="text-gray-500 text-sm leading-relaxed line-clamp-2">
                        {project.description}
                    </p>
                </div>
                </div>
            ))}
            </div>
        </div>

        {/* New Section: Because I love my designs */}
        <div id="gallery" className="pt-24 scroll-mt-24">
            <SectionTitle title="Gallery" subtitle="Because I love my designs." />
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {LOVED_DESIGNS.map((item) => (
                    <div 
                        key={item.id} 
                        className="group relative aspect-square overflow-hidden bg-gray-100 rounded-sm cursor-pointer"
                        onClick={() => setSelectedDesign(item)}
                    >
                        <img 
                            src={item.imageUrl} 
                            alt={item.title} 
                            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
                        />
                        <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-4">
                            <span className="text-white font-bold tracking-widest uppercase text-xs text-center">
                                {item.title}
                            </span>
                        </div>
                    </div>
                ))}
            </div>
        </div>

      </div>

      {/* Project Modal */}
      <Modal 
        isOpen={!!selectedProject} 
        onClose={() => setSelectedProject(null)}
        title={selectedProject?.title}
      >
        {selectedProject && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            <div className="space-y-6">
              {selectedProject.videoUrl ? (
                <div className="w-full aspect-video bg-black rounded-sm overflow-hidden">
                   <video controls className="w-full h-full object-cover">
                     <source src={selectedProject.videoUrl} type="video/mp4" />
                   </video>
                </div>
              ) : (
                <div className="w-full aspect-square md:aspect-video bg-gray-100 rounded-sm overflow-hidden">
                    <img src={selectedProject.imageUrl} alt={selectedProject.title} className="w-full h-full object-cover" />
                </div>
              )}

              <div className="flex gap-4">
                 {selectedProject.demoUrl && (
                     <a href={selectedProject.demoUrl} target="_blank" rel="noreferrer" className="px-6 py-3 bg-brand-yellow text-black font-medium text-sm hover:bg-black hover:text-white transition-colors flex items-center gap-2 rounded-sm">
                         <ExternalLink size={16} /> Live Demo
                     </a>
                 )}
              </div>
            </div>

            <div>
              <div className="flex flex-wrap gap-2 mb-8">
                {selectedProject.tags.map(tag => (
                    <span key={tag} className="px-3 py-1 bg-gray-100 text-xs text-gray-600 rounded-full">
                        {tag}
                    </span>
                ))}
              </div>

              <h4 className="text-xs font-bold uppercase tracking-widest text-gray-400 mb-4">Overview</h4>
              <p className="text-gray-800 leading-relaxed mb-8 text-lg font-light">
                {selectedProject.fullDescription || selectedProject.description}
              </p>

              <div className="border-t border-gray-100 pt-6 grid grid-cols-2 gap-6 text-sm">
                    <div>
                        <span className="block text-gray-400 mb-1">Role</span>
                        <span className="font-medium text-black">{selectedProject.role}</span>
                    </div>
                    <div>
                        <span className="block text-gray-400 mb-1">Timeline</span>
                        <span className="font-medium text-black">{selectedProject.date}</span>
                    </div>
              </div>
            </div>
          </div>
        )}
      </Modal>

      {/* Experience Modal */}
      <Modal
        isOpen={!!selectedExperience}
        onClose={() => setSelectedExperience(null)}
        title={selectedExperience?.company}
      >
        {selectedExperience && (
            <div>
                 <div className="mb-8 border-b border-gray-100 pb-8">
                     <h4 className="text-2xl font-bold text-black mb-2">{selectedExperience.role}</h4>
                     <p className="text-gray-400 text-sm mb-6">{selectedExperience.date}</p>
                     <ul className="space-y-3 text-gray-600 font-light">
                        {selectedExperience.description.map((item, i) => (
                            <li key={i}>• {item}</li>
                        ))}
                    </ul>
                </div>

                {selectedExperience.images && selectedExperience.images.length > 0 && (
                    <div>
                        <h5 className="text-sm font-bold uppercase tracking-widest text-gray-400 mb-6">Key Visuals & Projects</h5>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {selectedExperience.images.map((imgItem, idx) => (
                                <div key={idx} className="group/img relative aspect-[4/3] bg-gray-100 rounded-sm overflow-hidden shadow-sm hover:shadow-md transition-shadow">
                                    {imgItem.link ? (
                                        <a href={imgItem.link} target="_blank" rel="noreferrer" className="block w-full h-full relative">
                                            <img 
                                                src={imgItem.url} 
                                                alt={imgItem.alt || `${selectedExperience.company} visual ${idx + 1}`} 
                                                className={`w-full h-full ${idx <= 3 ? 'object-contain object-center' : 'object-cover'} transition-transform duration-700 group-hover/img:scale-105`} 
                                            />
                                            <div className="absolute inset-0 bg-black/20 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center">
                                                <ExternalLink className="text-white" size={32} />
                                            </div>
                                        </a>
                                    ) : (
                                        <img 
                                            src={imgItem.url} 
                                            alt={imgItem.alt || `${selectedExperience.company} visual ${idx + 1}`} 
                                            className={`w-full h-full ${idx <= 3 ? 'object-contain object-center' : 'object-cover'} transition-transform duration-700 group-hover/img:scale-105`} 
                                        />
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        )}
      </Modal>

      {/* Design Gallery Modal */}
      <Modal
        isOpen={!!selectedDesign}
        onClose={() => setSelectedDesign(null)}
        title="Gallery Preview"
      >
        {selectedDesign && (
            <div className="flex flex-col items-center">
                <div className="w-full max-h-[80vh] flex items-center justify-center bg-gray-50 rounded-sm overflow-hidden">
                    <img 
                        src={selectedDesign.imageUrl} 
                        alt={selectedDesign.title} 
                        className="max-w-full max-h-[75vh] object-contain"
                    />
                </div>
                <h3 className="mt-6 text-xl font-bold text-black">{selectedDesign.title}</h3>
            </div>
        )}
      </Modal>

    </section>
  );
};

