                {/* Right Column: Visuals Gallery */}
                {selectedExperience.images && selectedExperience.images.length > 0 && (
                    <div className="lg:w-2/3 space-y-8">
                        {selectedExperience.images.map((imgItem, idx) => {
                            // Check if this is one of the images that should be "contained" (documents, catalogs, posters)
                            // Based on user history: 1st (0), 2nd (1), 3rd (2), 4th (3), 5th (4), 6th (5), 7th (6), 8th (7), 9th (8), 10th (9)
                            // Basically all images added so far for Inara have required object-contain to be fully visible.
                            const isContained = idx <= 9; 

                            return (
                                <div key={idx} className="group relative bg-white rounded-sm overflow-hidden transition-all duration-300">
                                    {imgItem.link ? (
                                        <a href={imgItem.link} target="_blank" rel="noreferrer" className="block relative">
                                            <img 
                                                src={imgItem.url} 
                                                alt={imgItem.alt || `Project Visual ${idx + 1}`} 
                                                className={`w-full h-auto ${isContained ? 'object-contain object-center' : 'object-cover'} max-h-[600px]`} 
                                            />

                                            {/* Overlay for link indication */}
                                            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 transition-colors flex items-center justify-center pointer-events-none">
                                                <div className="bg-white text-black px-4 py-2 rounded-full text-xs font-bold uppercase tracking-widest shadow-lg opacity-0 translate-y-4 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300 flex items-center gap-2">
                                                    View Document <ExternalLink size={14} />
                                                </div>
                                            </div>
                                        </a>
                                    ) : (
                                        <img 
                                            src={imgItem.url} 
                                            alt={imgItem.alt || `Project Visual ${idx + 1}`} 
                                            className={`w-full h-auto ${isContained ? 'object-contain object-center' : 'object-cover'} max-h-[600px]`} 
                                        />
                                    )}

                                    {imgItem.alt && (
                                        <div className="mt-2 text-center px-4 py-2">
                                            <p className="text-xs text-gray-400 font-mono">{imgItem.alt}</p>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        )}
      </Modal>

      {/* Design Gallery Modal */}
      <Modal
        isOpen={!!selectedDesign}
        onClose={() => setSelectedDesign(null)}
        title="Gallery Preview"
      >
        {selectedDesign && (
            <div className="flex flex-col items-center">
                <div className="w-full max-h-[80vh] flex items-center justify-center bg-gray-50 rounded-sm overflow-hidden">
                    <img 
                        src={selectedDesign.imageUrl} 
                        alt={selectedDesign.title} 
                        className="max-w-full max-h-[75vh] object-contain"
                    />
                </div>
                <h3 className="mt-6 text-xl font-bold text-black">{selectedDesign.title}</h3>
            </div>
        )}
      </Modal>

    </section>
  );
};

