                            {exp.images && exp.images.length > 0 && (
                                <p className="mt-4 text-xs font-bold uppercase tracking-wider text-gray-400 group-hover:text-brand-yellow transition-colors">
                                    View Visuals & Projects
                                </p>
                            )}
                        </div>
                    </div>
                ))}
             </div>
        </div>

        <div id="projects" className="pt-10 scroll-mt-24">
            <SectionTitle title="Work" subtitle="Selected projects." />

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
            {PROJECTS.map((project) => (
