                                                </div>
                                            </div>
                                        </a>
                                    ) : (
                                        <img 
                                            src={imgItem.url} 
                                            alt={imgItem.alt || `Project Visual ${idx + 1}`} 
                                            className={`w-full h-auto ${isContained ? 'object-contain object-center' : 'object-cover'} max-h-[600px] ${isZoomed ? 'scale-110' : ''}`} 
                                        />
                                    )}

                                    {imgItem.alt && (
                                        <div className={`mt-2 text-center px-4 py-2 ${isZoomed ? '' : 'bg-white'}`}>
                                            <p className="text-xs text-gray-400 font-mono">{imgItem.alt}</p>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        )}
      </Modal>

      {/* Design Gallery Modal */}
      <Modal
        isOpen={!!selectedDesign}
        onClose={() => setSelectedDesign(null)}
        title="Gallery Preview"
      >
        {selectedDesign && (
            <div className="flex flex-col items-center">
                <div className="w-full max-h-[80vh] flex items-center justify-center bg-gray-50 rounded-sm overflow-hidden">
                    <img 
                        src={selectedDesign.imageUrl} 
                        alt={selectedDesign.title} 
                        className="max-w-full max-h-[75vh] object-contain"
                    />
                </div>
                <h3 className="mt-6 text-xl font-bold text-black">{selectedDesign.title}</h3>
            </div>
        )}
      </Modal>

    </section>
  );
};

